constraints:
1 ≤ N ≤ 10^{4}
1 ≤ arr[i] ≤ 5*10^{4}

expected time complexity: O(N*log(max(Arr[i])))
expected auxiliary space: O(1)

standard_solution_code:
import math

class Solution:

	def countMinOperations(self, arr, n):
		maxop = 0
		sub = 0
		for i in range(n):
			operations = 0
			while arr[i] != 0:
				if arr[i] % 2 == 0:
					arr[i] = arr[i] // 2
					operations += 1
				else:
					arr[i] = arr[i] - 1
					sub += 1
			maxop = max(maxop, operations)
		return maxop + sub
